using CoreBanking.Ledger.Domain.Customers;

namespace CoreBanking.Ledger.Domain.Tests.Customers;

public class CustomerTests
{
    // Fictitious CPF generated by the check digit algorithm. It belongs to no one.
    private static readonly CpfNumber Document = CpfNumber.Parse("39053344705");

    [Fact]
    public void Register_ValidData_CreatesCustomer()
    {
        var customer = Customer.Register("Maria Exemplo", Document);

        Assert.NotEqual(Guid.Empty, customer.Id);
        Assert.Equal("Maria Exemplo", customer.Name);
        Assert.Equal(Document, customer.Document);
    }

    [Theory]
    [InlineData("")]
    [InlineData("   ")]
    public void Register_EmptyName_Throws(string name)
    {
        var ex = Assert.Throws<DomainException>(() => Customer.Register(name, Document));

        Assert.Equal("customer.name_required", ex.Code);
    }
}
